// Package ccd validates structured device settings and renders OpenVPN CCD files.
package ccd

import (
	"encoding/binary"
	"fmt"
	"net/netip"
	"strings"
	"tunnelslate/internal/networkpolicy"
	"tunnelslate/internal/vpnoptions"
)

const Header = "# Managed by TunnelSlate CCD\n"

// IsManaged recognizes files generated by TunnelSlate.
func IsManaged(body string) bool {
	return strings.HasPrefix(body, Header)
}

type Settings struct {
	AccessMode      string   `json:"access_mode"`
	AllowedNetworks []string `json:"allowed_networks"`
	SiteNetworks    []string `json:"site_networks"`
	DNSDomainsMode  string   `json:"dns_domains_mode"`
	DNSDomain       string   `json:"dns_domain"`
	DNSSearch       []string `json:"dns_search"`
	StaticIP        string   `json:"static_ip"`
	DNSMode         string   `json:"dns_mode"`
	DNS             []string `json:"dns"`
	RoutesMode      string   `json:"routes_mode"`
	Routes          []string `json:"routes"`
	TunnelMode      string   `json:"tunnel_mode"`
	Revision        int64    `json:"revision"`
}

type Global struct {
	IsolateClients  bool     `json:"isolate_clients"`
	SiteToSite      bool     `json:"site_to_site"`
	SiteNAT         bool     `json:"site_nat"`
	SiteNetworks    []string `json:"site_networks"`
	DNSDomain       string   `json:"dns_domain"`
	DNSSearch       []string `json:"dns_search"`
	Network         string   `json:"network"`
	DNS             []string `json:"dns"`
	Routes          []string `json:"routes"`
	RedirectGateway bool     `json:"redirect_gateway"`
	Revision        int64    `json:"revision"`
}

type Range struct {
	Start string `json:"start"`
	End   string `json:"end"`
}

func Defaults() Settings {
	return Settings{AccessMode: "all", AllowedNetworks: []string{}, SiteNetworks: []string{}, DNSDomainsMode: "inherit", DNSSearch: []string{}, DNSMode: "inherit", DNS: []string{}, RoutesMode: "inherit", Routes: []string{}, TunnelMode: "inherit"}
}

func ipv4(n uint32) netip.Addr {
	var b [4]byte
	binary.BigEndian.PutUint32(b[:], n)
	return netip.AddrFrom4(b)
}

func Ranges(network string) (dynamic, fixed Range, err error) {
	p, err := netip.ParsePrefix(network)
	if err != nil || !p.Addr().Is4() || p.Bits() < 1 || p.Bits() > 29 {
		return dynamic, fixed, fmt.Errorf("Некорректная IPv4-подсеть VPN")
	}
	p = p.Masked()
	a := p.Addr().As4()
	base := binary.BigEndian.Uint32(a[:])
	size := uint32(1) << (32 - p.Bits())
	return Range{ipv4(base + 2).String(), ipv4(base + size/2 - 1).String()}, Range{ipv4(base + size/2).String(), ipv4(base + size - 2).String()}, nil
}

func Validate(s *Settings, network string) error {
	_, fixed, err := Ranges(network)
	if err != nil {
		return err
	}
	if s.DNSDomainsMode == "" {
		s.DNSDomainsMode = "inherit"
	}
	if s.DNSDomainsMode != "inherit" && s.DNSDomainsMode != "custom" {
		return fmt.Errorf("DNS domain mode must be inherit or custom")
	}
	if s.DNSDomainsMode == "inherit" {
		s.DNSDomain = ""
		s.DNSSearch = []string{}
	} else if err := vpnoptions.Domains(&s.DNSDomain, &s.DNSSearch); err != nil {
		return err
	}
	s.StaticIP = strings.TrimSpace(s.StaticIP)
	if s.StaticIP != "" {
		a, err := netip.ParseAddr(s.StaticIP)
		if err != nil || !a.Is4() || a.Compare(netip.MustParseAddr(fixed.Start)) < 0 || a.Compare(netip.MustParseAddr(fixed.End)) > 0 {
			return fmt.Errorf("Постоянный VPN-IP должен быть в диапазоне %s–%s", fixed.Start, fixed.End)
		}
		s.StaticIP = a.String()
	}
	policy := networkpolicy.Device{IP: s.StaticIP, Access: s.AccessMode, Allowed: s.AllowedNetworks, Sites: s.SiteNetworks}
	if err := networkpolicy.DeviceOptions(&policy, network); err != nil {
		return err
	}
	s.AccessMode, s.AllowedNetworks, s.SiteNetworks = policy.Access, policy.Allowed, policy.Sites
	if s.DNSMode != "inherit" && s.DNSMode != "custom" {
		return fmt.Errorf("Выберите общие или индивидуальные DNS")
	}
	if s.RoutesMode != "inherit" && s.RoutesMode != "custom" {
		return fmt.Errorf("Выберите общие или индивидуальные маршруты")
	}
	if s.TunnelMode != "inherit" && s.TunnelMode != "split" && s.TunnelMode != "full" {
		return fmt.Errorf("Выберите режим маршрутизации")
	}
	if s.DNSMode == "inherit" {
		s.DNS = []string{}
	} else {
		if len(s.DNS) < 1 || len(s.DNS) > 8 {
			return fmt.Errorf("Укажите от 1 до 8 DNS-серверов")
		}
		seen := map[string]bool{}
		dns := []string{}
		for _, value := range s.DNS {
			a, err := netip.ParseAddr(strings.TrimSpace(value))
			if err != nil || !a.Is4() || a.IsUnspecified() || a.IsMulticast() || a.IsLoopback() || a.String() == "255.255.255.255" {
				return fmt.Errorf("DNS-серверы должны быть доступными IPv4-адресами")
			}
			if !seen[a.String()] {
				dns = append(dns, a.String())
				seen[a.String()] = true
			}
		}
		s.DNS = dns
	}
	if s.RoutesMode == "inherit" {
		s.Routes = []string{}
	} else {
		if len(s.Routes) > 32 {
			return fmt.Errorf("Допускается не более 32 маршрутов")
		}
		routes := []string{}
		seen := map[string]bool{}
		for _, value := range s.Routes {
			p, err := netip.ParsePrefix(strings.TrimSpace(value))
			if err != nil || !p.Addr().Is4() || p.Bits() == 0 {
				return fmt.Errorf("Маршруты должны быть IPv4-сетями CIDR; для всего трафика выберите Full tunnel")
			}
			value = p.Masked().String()
			if !seen[value] {
				routes = append(routes, value)
				seen[value] = true
			}
		}
		s.Routes = routes
	}
	return nil
}

func Mask(p netip.Prefix) string { return ipv4(^uint32(0) << (32 - p.Bits())).String() }

func Customized(s Settings) bool {
	return s.AccessMode == "restricted" || len(s.SiteNetworks) > 0 || s.DNSDomainsMode == "custom" || s.StaticIP != "" || s.DNSMode != "inherit" || s.RoutesMode != "inherit" || s.TunnelMode != "inherit"
}

func Render(s Settings, global Global) ([]byte, error) {
	if err := Validate(&s, global.Network); err != nil {
		return nil, err
	}
	if !Customized(s) && !(global.SiteToSite && len(global.SiteNetworks) > 0) {
		return nil, nil
	}
	p := netip.MustParsePrefix(global.Network).Masked()
	var b strings.Builder
	b.WriteString(Header)
	if s.StaticIP != "" {
		fmt.Fprintf(&b, "ifconfig-push %s %s\n", s.StaticIP, Mask(p))
	}
	if global.SiteToSite {
		for _, site := range s.SiteNetworks {
			p := netip.MustParsePrefix(site)
			fmt.Fprintf(&b, "iroute %s %s\n", p.Addr(), Mask(p))
		}
	}
	if s.DNSMode == "custom" {
		b.WriteString("push-remove \"dhcp-option DNS \"\n")
		for _, dns := range s.DNS {
			fmt.Fprintf(&b, "push \"dhcp-option DNS %s\"\n", dns)
		}
	}
	if s.DNSDomainsMode == "custom" {
		b.WriteString("push-remove \"dhcp-option DOMAIN \"\n")
		b.WriteString("push-remove \"dhcp-option DOMAIN-SEARCH \"\n")
		if s.DNSDomain != "" {
			fmt.Fprintf(&b, "push \"dhcp-option DOMAIN %s\"\n", s.DNSDomain)
		}
		for _, domain := range s.DNSSearch {
			fmt.Fprintf(&b, "push \"dhcp-option DOMAIN-SEARCH %s\"\n", domain)
		}
	}
	// Rebuild IPv4 routes when DNS is overridden too, so inherited DNS host
	// routes disappear and the selected DNS still works in split tunnel.
	if s.DNSMode == "custom" || s.RoutesMode == "custom" || (global.SiteToSite && len(global.SiteNetworks) > 0) {
		b.WriteString("push-remove \"route \"\n")
		routes, dns := global.Routes, global.DNS
		if s.RoutesMode == "custom" {
			routes = s.Routes
		}
		if s.DNSMode == "custom" {
			dns = s.DNS
		}
		seen := map[string]bool{}
		add := func(route netip.Prefix) {
			route = route.Masked()
			if !seen[route.String()] {
				fmt.Fprintf(&b, "push \"route %s %s\"\n", route.Addr(), Mask(route))
				seen[route.String()] = true
			}
		}
		if global.SiteToSite {
			routes = append(append([]string{}, routes...), global.SiteNetworks...)
		}
		for _, value := range routes {
			route, err := netip.ParsePrefix(value)
			if err != nil || !route.Addr().Is4() {
				return nil, fmt.Errorf("Некорректный общий маршрут")
			}
			owned := false
			if global.SiteToSite {
				for _, site := range s.SiteNetworks {
					if route.Masked().String() == site {
						owned = true
						break
					}
				}
			}
			if !owned {
				add(route)
			}
		}
		for _, value := range dns {
			a, err := netip.ParseAddr(value)
			if err != nil || !a.Is4() {
				return nil, fmt.Errorf("Некорректный общий DNS")
			}
			if !p.Contains(a) {
				add(netip.PrefixFrom(a, 32))
			}
		}
	}
	if s.TunnelMode != "inherit" {
		b.WriteString("push-remove \"redirect-gateway\"\n")
		if s.TunnelMode == "full" {
			b.WriteString("push \"redirect-gateway def1 bypass-dhcp\"\n")
		}
	}
	return []byte(b.String()), nil
}
